public class Player : MonoBehaviour
{
    private Rigidbody rb;
    private GameManager gm;

    void Awake()
    {
        rb = GetComponent<Rigidbody>(); // self reference, safe
    }

    void Start()
    {
        gm = FindObjectOfType<GameManager>(); // other object, safe after all Awakes
    }
}
